MOVE_TO_TRASH
G0 Z5 F300
G0 Y280 F500
SET_PRINT_SUB_STATUS SUB_STATUS=z_tilt_adjust
Z_TILT_ADJUST


M104 S140
SET_PRINT_SUB_STATUS SUB_STATUS=wait_bed_temp
M190 S{bedtemp}
SET_PRINT_SUB_STATUS SUB_STATUS=wait_chamber_temp
M191 S{chambertemp}
M400
G4 P3000
SET_PRINT_SUB_STATUS SUB_STATUS=auto_bed_adjust
G29
G0 Z50 F600
G0 X240 Y25 F2000
G0 X260 Y5 F500
{% if printer.save_variables.variables.box_count >= 1 and printer["box_extras"] and printer.save_variables.variables.enable_box == 1 %}
BUFFER_MONITORING ENABLE=1
{% endif %}
M191 S{chambertemp}
M109 S{hotendtemp}
M204 S10000
M106 P4 S{Polar_cooler}

set_zoffset
ENABLE_ALL_SENSOR
save_last_file
